&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;δεδομένα επεξεργασίας, καдриσμός, εκπαιδεύσεις&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;φιλτράρισμένο&lt;/strong&gt;— Μόνη όραση&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;foundry/private/&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
