&lt;h2 id=&quot;προμηθίες&quot;&gt;Προμηθίες&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Οι promises χρησιμοποιούνται για την εκτέλεση ασυγχρονών λειτουργιών.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Παράδειγμα βαθμολογίας :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-typescript hljs&quot; data-lang=&quot;typescript&quot;&gt;const promise = new Promise&amp;lt;string&amp;gt;((resolve) =&amp;gt; {
    // Code asynchrone ici
    resolve(&quot;Succès&quot;);
});

promise.then((result) =&amp;gt; {
    console.log(result);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
